import sys

class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

def insert(root, key):
    if root is None:
        return Node(key)
    if key < root.data:
        root.left = insert(root.left, key)
    elif key > root.data:
        root.right = insert(root.right, key)
    return root

def find_min(node):
    if node is None:
        return None
    current = node
    while current.left:
        current = current.left
    return current.data

def find_max(node):
    if node is None:
        return None
    current = node
    while current.right:
        current = current.right
    return current.data

def find(root, key):
    if root is None:
        return False
    if root.data == key:
        return True
    elif key < root.data:
        return find(root.left, key)
    else:
        return find(root.right, key)

def min_value_node(node):
    current = node
    while current and current.left:
        current = current.left
    return current

def delete_node(root, key):
    if root is None:
        return root

    if key < root.data:
        root.left = delete_node(root.left, key)
    elif key > root.data:
        root.right = delete_node(root.right, key)
    else:
        if root.left is None:
            return root.right
        elif root.right is None:
            return root.left

        temp = min_value_node(root.right)
        root.data = temp.data
        root.right = delete_node(root.right, temp.data)

    return root

def in_order_traversal(root, result):
    if root:
        in_order_traversal(root.left, result)
        result.append(root.data)
        in_order_traversal(root.right, result)

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    root = None
    index = 1

    for i in range(n):
        if index >= len(data):
            break

        op = data[index]
        index += 1

        if op == "INSERT":
            if index < len(data):
                key = int(data[index])
                index += 1
                root = insert(root, key)

        elif op == "DELETE":
            if index < len(data):
                key = int(data[index])
                index += 1
                if not find(root, key):
                    print("Tower not found")
                else:
                    root = delete_node(root, key)

        elif op == "MIN":
            result = find_min(root)
            if result is not None:
                print(result)

        elif op == "MAX":
            result = find_max(root)
            if result is not None:
                print(result)

        elif op == "FIND":
            if index < len(data):
                key = int(data[index])
                index += 1
                if find(root, key):
                    print("Found")
                else:
                    print("Not Found")

        elif op == "PRINT":
            result = []
            in_order_traversal(root, result)
            print(" ".join(map(str, result)))

if __name__ == "__main__":
    main()
